import re,json,pandas as pd
s=open('accessibility_b3_v20.html').read();d=pd.read_csv('b3_all_origins.csv'); assert d.origin_id.is_unique
x=d.loc[d.network_covered.eq(True)].copy(); c7='age_7_N_venue_proxy_within_30min';c13='age_13_N_venue_proxy_within_30min';assert x[[c7,c13]].notna().all().all();delta=x[c13]-x[c7];counts=[int((delta<0).sum()),int((delta==0).sum()),int((delta>0).sum())];n=len(delta);pct=[round(v/n*100,1) for v in counts];assert n==30224 and counts==[25277,3332,1615]; print('counts',counts,'percent',pct,'median',delta.median())
m=re.search(r'const slides=(\[.*?\]);let current=',s,re.S);a=json.loads(m.group(1));z=a[7]
chart='''<div class="pair-summary"><div class="pair-title">В одной жилой точке: число координат для 13 лет относительно 7 лет</div><div class="pair-bar" aria-label="Меньше: 83,6 процента; равно: 11,0 процента; больше: 5,3 процента"><i style="width:83.6322%"></i><i style="width:11.0244%"></i><i style="width:5.3434%"></i></div><div class="pair-key"><span><b>83,6%</b> меньше</span><span><b>11,0%</b> равно</span><span><b>5,3%</b> больше</span></div></div>'''
z['body']+=chart
z['foot']='B3 · 30 минут · 30 224 подключённые точки · Navigator / BlocksNet · предварительно'
z['note']+=' Для каждой подключённой жилой точки сравнили число достижимых координат для двух возрастов. В 83,6% точек оно меньше для 13 лет, чем для 7; в 11,0% равно и в 5,3% больше. Равенство включает случаи без найденных координат для обоих возрастов. Это свойства опубликованного предложения, а не оценка числа детей или самостоятельности.'
s=s[:m.start(1)]+json.dumps(a,ensure_ascii=False)+s[m.end(1):]
css='''<style>.body:has(.pair-summary){gap:.48cqw}.body:has(.pair-summary) .bars{gap:.42cqw}.body:has(.pair-summary) .track{height:1.28cqw}.body:has(.pair-summary) .explain{padding:.65% 1.2%;font-size:clamp(9px,1.05cqw,16px)}.pair-summary{width:100%;background:#f3f7f7;padding:1% 1.5%;color:#253c4d}.pair-title{font-size:clamp(10px,1.12cqw,17px);margin-bottom:.45cqw}.pair-bar{display:flex;height:1.25cqw;min-height:7px;width:100%;overflow:hidden}.pair-bar i:nth-child(1){background:#315b78}.pair-bar i:nth-child(2){background:#9eafb6}.pair-bar i:nth-child(3){background:#ba7550}.pair-key{display:flex;justify-content:space-between;gap:1%;font-size:clamp(10px,1.1cqw,16px);margin-top:.35cqw}.pair-key b{font-size:1.05em}</style>'''
s=s.replace('</head>',css+'</head>',1);s=s.replace('<details class="sources">','<details class="sources"><p><a href="https://github.com/OlesyaValukhova/-/blob/master/results/blocksnet-b3-citywide-20261111/full_observable/b3-by-origin.csv">B3: попарные результаты по жилым точкам</a> · 387 неподключённых точек исключены; равенство включает нулевой выбор для обоих возрастов.</p>',1)
open('accessibility_b3_v21.html','w').write(s)
